import React from 'react';
import { FiUser, FiMapPin, FiTruck, FiCreditCard, FiCheckCircle } from 'react-icons/fi';

const STEPS = [
  { id: 1, label: 'Customer Info', icon: FiUser },
  { id: 2, label: 'Address', icon: FiMapPin },
  { id: 3, label: 'Shipping', icon: FiTruck },
  { id: 4, label: 'Payment', icon: FiCreditCard },
  { id: 5, label: 'Review', icon: FiCheckCircle }
];

const CheckoutProgress = ({ currentStep = 1, onStepClick }) => {
  return (
    <div
      style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        width: '100%',
        backgroundColor: 'var(--bg-secondary, #0c1c28)',
        border: '1px solid var(--border-color, rgba(255, 255, 255, 0.08))',
        borderRadius: '12px',
        padding: '16px 24px',
        margin: '20px 0 30px 0',
        overflowX: 'auto'
      }}
    >
      {STEPS.map((step, idx) => {
        const Icon = step.icon;
        const isActive = step.id === currentStep;
        const isCompleted = step.id < currentStep;

        return (
          <React.Fragment key={step.id}>
            <div
              onClick={() => isCompleted && onStepClick && onStepClick(step.id)}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: '8px',
                cursor: isCompleted ? 'pointer' : 'default',
                opacity: isCompleted || isActive ? 1 : 0.4
              }}
            >
              <div
                style={{
                  width: '32px',
                  height: '32px',
                  borderRadius: '50%',
                  backgroundColor: isCompleted ? '#22c55e' : isActive ? '#D51E0B' : 'rgba(255, 255, 255, 0.1)',
                  color: '#ffffff',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  fontSize: '14px',
                  fontWeight: '800'
                }}
              >
                <Icon size={16} />
              </div>
              <span
                style={{
                  fontSize: '13px',
                  fontWeight: isActive ? '800' : '600',
                  color: isActive ? '#ffffff' : isCompleted ? '#22c55e' : 'var(--text-secondary, #9ca3af)',
                  whiteSpace: 'nowrap'
                }}
              >
                {step.label}
              </span>
            </div>

            {idx < STEPS.length - 1 && (
              <div
                style={{
                  flex: 1,
                  height: '2px',
                  backgroundColor: isCompleted ? '#22c55e' : 'rgba(255, 255, 255, 0.1)',
                  margin: '0 12px',
                  minWidth: '20px'
                }}
              />
            )}
          </React.Fragment>
        );
      })}
    </div>
  );
};

export default CheckoutProgress;
