import productService from './productService';

const POPULAR_SEARCHES = [
  'RTX 4090',
  'Core i9',
  'Gaming Laptop',
  '4K Monitor',
  'NVMe SSD',
  'Mechanical Keyboard',
  'Ryzen 7',
  'Logitech Mouse',
  'Corsair RAM'
];

export const searchService = {
  /**
   * Performs multi-field search across product catalog
   * @param {string} query 
   * @param {Object} options 
   * @returns {Promise<{ products: Array, suggestions: Array, total: number }>}
   */
  async search(query = '', options = {}) {
    const trimmed = query.trim().toLowerCase();
    if (!trimmed) {
      return { products: [], suggestions: [], total: 0 };
    }

    const { products: catalog } = await productService.getProducts({});

    // 1. Multi-field filtering & relevance scoring
    const matchedProducts = [];

    catalog.forEach((prod) => {
      let score = 0;
      const name = prod.name.toLowerCase();
      const brand = prod.brand.toLowerCase();
      const category = prod.category.toLowerCase();
      const subCategory = (prod.subCategory || '').toLowerCase();
      const sku = prod.sku.toLowerCase();

      // Score calculation for relevance ranking
      if (name.startsWith(trimmed)) score += 100;
      else if (name.includes(trimmed)) score += 50;

      if (brand.startsWith(trimmed)) score += 40;
      else if (brand.includes(trimmed)) score += 20;

      if (category.startsWith(trimmed)) score += 30;
      else if (category.includes(trimmed)) score += 15;

      if (subCategory.includes(trimmed)) score += 25;
      if (sku.includes(trimmed)) score += 60;

      if (score > 0) {
        matchedProducts.push({ product: prod, score });
      }
    });

    // Sort by relevance score descending
    matchedProducts.sort((a, b) => b.score - a.score);
    const finalProducts = matchedProducts.map((m) => m.product);

    // 2. Generate Autocomplete Suggestions
    const suggestionsSet = new Set();

    // Check popular terms matching query
    POPULAR_SEARCHES.forEach((term) => {
      if (term.toLowerCase().includes(trimmed)) {
        suggestionsSet.add(term);
      }
    });

    // Add matching categories and brands to suggestions
    catalog.forEach((prod) => {
      if (prod.brand.toLowerCase().includes(trimmed)) {
        suggestionsSet.add(prod.brand);
      }
      if (prod.category.toLowerCase().includes(trimmed)) {
        suggestionsSet.add(prod.category);
      }
      if (prod.subCategory && prod.subCategory.toLowerCase().includes(trimmed)) {
        suggestionsSet.add(prod.subCategory);
      }
    });

    const suggestions = Array.from(suggestionsSet).slice(0, 5);

    return {
      products: options.limit ? finalProducts.slice(0, options.limit) : finalProducts,
      suggestions,
      total: finalProducts.length
    };
  },

  /**
   * Gets popular search keywords list
   */
  getPopularSearches() {
    return POPULAR_SEARCHES;
  }
};

export default searchService;
