import React from 'react';
import { useNavigate } from 'react-router-dom';
import { FiClock, FiX, FiTrendingUp, FiChevronRight, FiSearch } from 'react-icons/fi';
import HighlightText from '../../utils/highlightText';
import './SearchDropdown.css';

const SearchDropdown = ({
  query = '',
  results = [],
  suggestions = [],
  recentSearches = [],
  popularSearches = [],
  activeHoverIndex = -1,
  loading = false,
  onSelectSearch,
  onRemoveRecent,
  onClearRecent,
  onClose
}) => {
  const navigate = useNavigate();

  const handleProductClick = (prod) => {
    onSelectSearch(prod.name);
    onClose();
    navigate(`/product/${prod.id}`);
  };

  const handleTermClick = (term) => {
    onSelectSearch(term);
  };

  const hasQuery = query.trim().length > 0;

  return (
    <div className="search-dropdown-menu" tabIndex="-1">
      {loading && (
        <div className="search-drop-loading">
          <div className="search-drop-spinner" />
          <span>Searching catalog...</span>
        </div>
      )}

      {/* ================= 1. LIVE SEARCH RESULTS ================= */}
      {hasQuery && !loading && (
        <div className="search-drop-section">
          <div className="search-drop-section-title">Matching Products ({results.length})</div>

          {results.length === 0 ? (
            <div className="search-drop-empty">
              <span>No products matching "<strong>{query}</strong>"</span>
              <p>Check spelling or try popular keywords below.</p>
            </div>
          ) : (
            <div className="search-results-list">
              {results.map((prod, idx) => {
                const isActive = activeHoverIndex === idx;
                return (
                  <div
                    key={prod.id}
                    className={`search-item-card ${isActive ? 'active-hover' : ''}`}
                    onClick={() => handleProductClick(prod)}
                  >
                    <img
                      src={prod.thumbnail || prod.images[0]}
                      alt={prod.name}
                      className="search-item-img"
                    />
                    <div className="search-item-info">
                      <div className="search-item-top">
                        <span className="search-item-brand">{prod.brand}</span>
                        <span className="search-item-cat">{prod.category}</span>
                      </div>
                      <div className="search-item-title">
                        <HighlightText text={prod.name} query={query} />
                      </div>
                      <div className="search-item-price-row">
                        <span className="search-item-price">৳{prod.price.toLocaleString('en-IN')}</span>
                        {prod.oldPrice > prod.price && (
                          <span className="search-item-old-price">৳{prod.oldPrice.toLocaleString('en-IN')}</span>
                        )}
                        {prod.discount > 0 && (
                          <span className="search-item-disc">-{prod.discount}%</span>
                        )}
                      </div>
                    </div>
                    <FiChevronRight className="search-item-arrow" />
                  </div>
                );
              })}
            </div>
          )}

          {/* Autocomplete Keyword Suggestions */}
          {suggestions.length > 0 && (
            <div className="search-drop-suggestions">
              <div className="search-drop-sub-title">Suggestions:</div>
              <div className="search-chips-row">
                {suggestions.map((sug, i) => (
                  <button
                    key={i}
                    type="button"
                    className="search-chip-btn"
                    onClick={() => handleTermClick(sug)}
                  >
                    <FiSearch size={12} /> <HighlightText text={sug} query={query} />
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {/* ================= 2. EMPTY QUERY: RECENT & POPULAR SEARCHES ================= */}
      {!hasQuery && (
        <div className="search-drop-idle">
          {/* Recent Searches */}
          {recentSearches.length > 0 && (
            <div className="search-drop-group">
              <div className="search-group-head">
                <span><FiClock size={14} /> Recent Searches</span>
                <button type="button" className="search-clear-all" onClick={onClearRecent}>
                  Clear All
                </button>
              </div>
              <div className="search-recent-list">
                {recentSearches.map((term, idx) => (
                  <div key={idx} className="search-recent-row">
                    <span onClick={() => handleTermClick(term)} className="search-recent-text">
                      <FiClock size={13} /> {term}
                    </span>
                    <button
                      type="button"
                      className="search-recent-del"
                      onClick={(e) => {
                        e.stopPropagation();
                        onRemoveRecent(term);
                      }}
                      title="Remove"
                    >
                      <FiX size={14} />
                    </button>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Popular Searches */}
          <div className="search-drop-group" style={{ marginTop: '16px' }}>
            <div className="search-group-head">
              <span><FiTrendingUp size={14} /> Popular Searches</span>
            </div>
            <div className="search-chips-row">
              {popularSearches.map((pop, idx) => (
                <button
                  key={idx}
                  type="button"
                  className="search-chip-btn popular"
                  onClick={() => handleTermClick(pop)}
                >
                  <FiTrendingUp size={12} /> {pop}
                </button>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* View All Search Results Footer */}
      {hasQuery && results.length > 0 && (
        <div className="search-drop-footer" onClick={() => onSelectSearch(query)}>
          <span>See all matching results for "<strong>{query}</strong>"</span>
          <FiChevronRight />
        </div>
      )}
    </div>
  );
};

export default SearchDropdown;
