import React, { useRef } from 'react';
import { FiSearch, FiX } from 'react-icons/fi';
import useSearch from '../../hooks/useSearch';
import SearchDropdown from './SearchDropdown';

const SearchBar = ({ className = '' }) => {
  const containerRef = useRef(null);
  const inputRef = useRef(null);

  const {
    query,
    results,
    suggestions,
    recentSearches,
    popularSearches,
    activeHoverIndex,
    loading,
    isDropdownOpen,
    handleQueryChange,
    submitSearch,
    handleKeyDown,
    openDropdown,
    closeDropdown,
    removeRecent,
    clearAllRecent
  } = useSearch();

  const handleFormSubmit = (e) => {
    e.preventDefault();
    submitSearch();
  };

  const handleClear = () => {
    handleQueryChange('');
    if (inputRef.current) inputRef.current.focus();
  };

  const handleSelectSearch = (term) => {
    handleQueryChange(term);
    submitSearch(term);
  };

  return (
    <div
      ref={containerRef}
      className={`hdr-search ${className}`}
      style={{ position: 'relative' }}
      onBlur={(e) => {
        if (containerRef.current && !containerRef.current.contains(e.relatedTarget)) {
          closeDropdown();
        }
      }}
    >
      <form onSubmit={handleFormSubmit} style={{ width: '100%', display: 'flex', alignItems: 'center' }}>
        <FiSearch className="hdr-search-ic" size={18} />

        <input
          ref={inputRef}
          type="search"
          role="combobox"
          aria-expanded={isDropdownOpen ? 'true' : 'false'}
          aria-controls="search-dropdown-list"
          aria-autocomplete="list"
          aria-label="Search for products, brands and more"
          placeholder="Search for products, brands and more..."
          value={query}
          onFocus={openDropdown}
          onChange={(e) => handleQueryChange(e.target.value)}
          onKeyDown={handleKeyDown}
        />

        {query && (
          <button type="button" className="hdr-search-clear" onClick={handleClear} title="Clear search">
            <FiX size={16} />
          </button>
        )}

        <button type="submit" className="hdr-search-btn">
          <FiSearch size={17} /> <span>Search</span>
        </button>
      </form>

      {/* Live Search Results Dropdown */}
      {isDropdownOpen && (
        <div id="search-dropdown-list">
          <SearchDropdown
            query={query}
            results={results}
            suggestions={suggestions}
            recentSearches={recentSearches}
            popularSearches={popularSearches}
            activeHoverIndex={activeHoverIndex}
            loading={loading}
            onSelectSearch={handleSelectSearch}
            onRemoveRecent={removeRecent}
            onClearRecent={clearAllRecent}
            onClose={closeDropdown}
          />
        </div>
      )}
    </div>
  );
};

export default React.memo(SearchBar);
