import React, { useState } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { useNotification } from '../context/NotificationContext';
import { FiLock, FiMail, FiZap, FiShield, FiBriefcase, FiUser } from 'react-icons/fi';

const Login = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { login } = useAuth();
  const { error: showError, success: showSuccess } = useNotification();

  const [formData, setFormData] = useState({ email: 'customer@startech.test', password: 'password' });
  const [selectedRole, setSelectedRole] = useState('Customer');
  const [loading, setLoading] = useState(false);

  // Intended destination after login
  const fromLocation = location.state?.from?.pathname;

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleDemoSelect = (roleType, email) => {
    setSelectedRole(roleType);
    setFormData({ email, password: 'password' });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const success = await login(formData.email, formData.password, selectedRole);

      if (success) {
        showSuccess(`Welcome back! Logged in as ${selectedRole}`);

        // Redirect to intended page or default role dashboard
        if (fromLocation) {
          navigate(fromLocation, { replace: true });
        } else if (selectedRole === 'Admin') {
          navigate('/admin-dashboard', { replace: true });
        } else if (selectedRole === 'Seller') {
          navigate('/seller-dashboard', { replace: true });
        } else {
          navigate('/dashboard', { replace: true });
        }
      } else {
        showError('Login failed. Please verify credentials.');
      }
    } catch (err) {
      showError('An error occurred during authentication.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      style={{
        padding: '60px 20px',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        minHeight: '75vh',
        background: 'var(--bg)',
        fontFamily: "'Inter', sans-serif"
      }}
    >
      <div style={{ width: '100%', maxWidth: '440px' }}>
        <div
          style={{
            backgroundColor: 'var(--bg-secondary)',
            border: '1px solid var(--border-color)',
            borderRadius: '16px',
            padding: '40px 32px',
            boxShadow: '0 20px 40px rgba(0,0,0,0.15)',
            position: 'relative',
            overflow: 'hidden'
          }}
        >
          {/* Top Red Bar */}
          <div
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              right: 0,
              height: '4px',
              backgroundColor: '#D51E0B'
            }}
          />

          {/* Logo Header */}
          <div style={{ textAlign: 'center', marginBottom: '28px' }}>
            <div style={{ display: 'inline-flex', alignItems: 'center', justifyContent: 'center', width: '48px', height: '48px', borderRadius: '12px', backgroundColor: '#D51E0B', color: '#fff', marginBottom: '12px' }}>
              <FiZap size={28} />
            </div>
            <h1 style={{ fontSize: '24px', fontWeight: '800', color: 'var(--text-primary)', marginBottom: '6px' }}>
              Sign In to StarTech
            </h1>
            <p style={{ color: 'var(--text-secondary)', fontSize: '14px' }}>
              Access your orders, wishlist, and dashboard
            </p>
          </div>

          {/* Quick Role Switcher Buttons */}
          <div style={{ marginBottom: '24px' }}>
            <label style={{ fontSize: '12px', fontWeight: '700', textTransform: 'uppercase', tracking: '0.5px', color: 'var(--text-secondary)', display: 'block', marginBottom: '8px' }}>
              Select Account Role Perspective:
            </label>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '8px' }}>
              <button
                type="button"
                onClick={() => handleDemoSelect('Customer', 'customer@startech.test')}
                style={{
                  padding: '8px',
                  borderRadius: '8px',
                  border: selectedRole === 'Customer' ? '2px solid #D51E0B' : '1px solid var(--border-color)',
                  backgroundColor: selectedRole === 'Customer' ? 'rgba(213, 30, 11, 0.1)' : 'var(--bg)',
                  color: selectedRole === 'Customer' ? '#D51E0B' : 'var(--text-secondary)',
                  fontWeight: '600',
                  fontSize: '12px',
                  cursor: 'pointer',
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  gap: '4px'
                }}
              >
                <FiUser size={16} /> Customer
              </button>

              <button
                type="button"
                onClick={() => handleDemoSelect('Seller', 'seller@startech.test')}
                style={{
                  padding: '8px',
                  borderRadius: '8px',
                  border: selectedRole === 'Seller' ? '2px solid #3b82f6' : '1px solid var(--border-color)',
                  backgroundColor: selectedRole === 'Seller' ? 'rgba(59, 130, 246, 0.1)' : 'var(--bg)',
                  color: selectedRole === 'Seller' ? '#3b82f6' : 'var(--text-secondary)',
                  fontWeight: '600',
                  fontSize: '12px',
                  cursor: 'pointer',
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  gap: '4px'
                }}
              >
                <FiBriefcase size={16} /> Seller
              </button>

              <button
                type="button"
                onClick={() => handleDemoSelect('Admin', 'admin@startech.test')}
                style={{
                  padding: '8px',
                  borderRadius: '8px',
                  border: selectedRole === 'Admin' ? '2px solid #ef4444' : '1px solid var(--border-color)',
                  backgroundColor: selectedRole === 'Admin' ? 'rgba(239, 68, 68, 0.1)' : 'var(--bg)',
                  color: selectedRole === 'Admin' ? '#ef4444' : 'var(--text-secondary)',
                  fontWeight: '600',
                  fontSize: '12px',
                  cursor: 'pointer',
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  gap: '4px'
                }}
              >
                <FiShield size={16} /> Admin
              </button>
            </div>
          </div>

          <form onSubmit={handleSubmit}>
            <div style={{ marginBottom: '16px' }}>
              <label style={{ display: 'block', fontSize: '13px', fontWeight: '600', color: 'var(--text-primary)', marginBottom: '6px' }}>
                Email Address
              </label>
              <div style={{ position: 'relative' }}>
                <FiMail style={{ position: 'absolute', left: '12px', top: '14px', color: 'var(--text-secondary)' }} />
                <input
                  type="email"
                  name="email"
                  placeholder="Enter email address"
                  value={formData.email}
                  onChange={handleInputChange}
                  required
                  style={{
                    width: '100%',
                    padding: '12px 12px 12px 38px',
                    border: '1px solid var(--border-color)',
                    borderRadius: '8px',
                    backgroundColor: 'var(--bg)',
                    color: 'var(--text-primary)',
                    fontSize: '14px'
                  }}
                />
              </div>
            </div>

            <div style={{ marginBottom: '20px' }}>
              <label style={{ display: 'block', fontSize: '13px', fontWeight: '600', color: 'var(--text-primary)', marginBottom: '6px' }}>
                Password
              </label>
              <div style={{ position: 'relative' }}>
                <FiLock style={{ position: 'absolute', left: '12px', top: '14px', color: 'var(--text-secondary)' }} />
                <input
                  type="password"
                  name="password"
                  placeholder="Enter password"
                  value={formData.password}
                  onChange={handleInputChange}
                  required
                  style={{
                    width: '100%',
                    padding: '12px 12px 12px 38px',
                    border: '1px solid var(--border-color)',
                    borderRadius: '8px',
                    backgroundColor: 'var(--bg)',
                    color: 'var(--text-primary)',
                    fontSize: '14px'
                  }}
                />
              </div>
            </div>

            <button
              type="submit"
              disabled={loading}
              className="btn btn-primary"
              style={{
                width: '100%',
                padding: '14px',
                fontSize: '15px',
                fontWeight: '700',
                borderRadius: '8px',
                backgroundColor: '#D51E0B',
                color: '#fff',
                border: 'none',
                cursor: 'pointer'
              }}
            >
              {loading ? 'Authenticating...' : `Login as ${selectedRole}`}
            </button>
          </form>

          <div style={{ marginTop: '24px', textAlign: 'center' }}>
            <p style={{ color: 'var(--text-secondary)', fontSize: '14px' }}>
              Don't have an account? <Link to="/register" style={{ color: '#D51E0B', fontWeight: '600' }}>Create Account</Link>
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;
