import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { FiTrash2, FiChevronRight, FiX, FiShoppingCart, FiPlus } from 'react-icons/fi';
import { BsArrowLeftRight } from 'react-icons/bs';
import useCompare from '../hooks/useCompare';
import { useCart } from '../context/CartContext';
import './Category.css';

const Comparison = () => {
  const { compareItems, compareCount, removeFromCompare, clearCompare } = useCompare();
  const { addToCart } = useCart();
  const [highlightDifferences, setHighlightDifferences] = useState(false);

  // Extract all unique specification keys across compare products
  const specKeysSet = new Set();
  compareItems.forEach((prod) => {
    if (prod.specifications && typeof prod.specifications === 'object') {
      Object.values(prod.specifications).forEach((groupFields) => {
        if (groupFields && typeof groupFields === 'object') {
          Object.keys(groupFields).forEach((k) => specKeysSet.add(k));
        }
      });
    }
  });

  const specKeys = Array.from(specKeysSet);

  const getSpecValue = (product, specKey) => {
    if (!product.specifications) return 'N/A';
    let found = 'N/A';
    Object.values(product.specifications).forEach((groupFields) => {
      if (groupFields && groupFields[specKey] !== undefined) {
        found = groupFields[specKey];
      }
    });
    return found;
  };

  const isSpecDifferent = (specKey) => {
    if (compareItems.length <= 1) return false;
    const values = compareItems.map((prod) => getSpecValue(prod, specKey));
    return !values.every((v) => v === values[0]);
  };

  return (
    <div className="cat" style={{ paddingBottom: '60px' }}>
      {/* Breadcrumb */}
      <div className="cat-breadcrumb">
        <div className="container">
          <Link to="/">Home</Link> <FiChevronRight />
          <span>Product Comparison</span>
        </div>
      </div>

      {/* Header */}
      <div className="container cat-header" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div>
          <h1>Product Comparison ({compareCount}/4)</h1>
          <p>Compare tech specifications side-by-side</p>
        </div>

        {compareCount > 0 && (
          <div style={{ display: 'flex', gap: '12px', alignItems: 'center' }}>
            <label style={{ display: 'flex', alignItems: 'center', gap: '6px', fontSize: '13px', color: '#ffffff', cursor: 'pointer' }}>
              <input
                type="checkbox"
                checked={highlightDifferences}
                onChange={(e) => setHighlightDifferences(e.target.checked)}
                style={{ accentColor: '#D51E0B' }}
              />
              Highlight Differences
            </label>

            <button
              type="button"
              onClick={clearCompare}
              style={{
                padding: '8px 14px',
                backgroundColor: 'rgba(239, 68, 68, 0.1)',
                color: '#ef4444',
                border: '1px solid rgba(239, 68, 68, 0.3)',
                borderRadius: '8px',
                fontWeight: '700',
                fontSize: '13px',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: '6px'
              }}
            >
              <FiTrash2 /> Clear Comparison
            </button>
          </div>
        )}
      </div>

      <div className="container">
        {compareCount === 0 ? (
          <div
            style={{
              textAlign: 'center',
              padding: '80px 20px',
              backgroundColor: 'var(--bg-secondary, #0c1c28)',
              border: '1px solid var(--border-color, rgba(255,255,255,0.08))',
              borderRadius: '16px'
            }}
          >
            <div style={{ width: '80px', height: '80px', borderRadius: '50%', backgroundColor: 'rgba(59, 130, 246, 0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 16px auto', color: '#3b82f6' }}>
              <BsArrowLeftRight size={40} />
            </div>
            <h2 style={{ color: '#ffffff', fontSize: '22px', fontWeight: '800', marginBottom: '8px' }}>
              No Products Selected for Comparison
            </h2>
            <p style={{ color: '#9ca3af', marginBottom: '24px', maxWidth: '420px', margin: '0 auto 24px auto' }}>
              Click the compare icon on up to 4 products to compare their prices, performance, memory, and specifications side-by-side.
            </p>
            <Link to="/category/component" className="btn btn-primary" style={{ display: 'inline-flex', alignItems: 'center', gap: '8px' }}>
              <FiPlus /> Add Products to Compare
            </Link>
          </div>
        ) : (
          <div style={{ overflowX: 'auto', backgroundColor: 'var(--bg-secondary, #0c1c28)', border: '1px solid var(--border-color, rgba(255,255,255,0.08))', borderRadius: '16px', padding: '16px' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', color: '#ffffff' }}>
              <thead>
                <tr>
                  <th style={{ width: '180px', padding: '16px', backgroundColor: '#081621', color: '#9ca3af', fontSize: '13px', fontWeight: '800', borderBottom: '2px solid rgba(255,255,255,0.1)' }}>
                    Products
                  </th>
                  {compareItems.map((prod) => (
                    <th key={prod.id} style={{ minWidth: '220px', padding: '16px', backgroundColor: '#081621', borderBottom: '2px solid rgba(255,255,255,0.1)', verticalAlign: 'top' }}>
                      <div style={{ display: 'flex', flexDirection: 'column', gap: '10px', height: '100%' }}>
                        <button
                          type="button"
                          onClick={() => removeFromCompare(prod.id)}
                          style={{ alignSelf: 'flex-end', background: 'none', border: 'none', color: '#ef4444', cursor: 'pointer' }}
                          title="Remove"
                        >
                          <FiX size={18} />
                        </button>
                        <img
                          src={prod.thumbnail || (prod.images && prod.images[0])}
                          alt={prod.name}
                          style={{ height: '120px', objectFit: 'contain', margin: '0 auto' }}
                        />
                        <Link to={`/product/${prod.id}`} style={{ color: '#ffffff', fontWeight: '700', fontSize: '14px', lineHeight: 1.3, textDecoration: 'none' }}>
                          {prod.name}
                        </Link>
                        <div style={{ fontSize: '18px', fontWeight: '900', color: '#D51E0B', marginTop: 'auto' }}>
                          ৳{prod.price.toLocaleString('en-IN')}
                        </div>
                        <button
                          type="button"
                          onClick={() => addToCart(prod, 1)}
                          style={{
                            padding: '8px',
                            backgroundColor: '#D51E0B',
                            color: '#ffffff',
                            fontWeight: '700',
                            fontSize: '12px',
                            borderRadius: '6px',
                            border: 'none',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            gap: '4px',
                            cursor: 'pointer',
                            marginTop: '8px'
                          }}
                        >
                          <FiShoppingCart /> Add to Cart
                        </button>
                      </div>
                    </th>
                  ))}
                </tr>
              </thead>

              <tbody>
                {/* Brand Row */}
                <tr>
                  <td style={{ padding: '12px 16px', fontWeight: '700', color: '#9ca3af', borderBottom: '1px solid rgba(255,255,255,0.06)' }}>Brand</td>
                  {compareItems.map((p) => (
                    <td key={p.id} style={{ padding: '12px 16px', borderBottom: '1px solid rgba(255,255,255,0.06)', fontWeight: '600' }}>{p.brand}</td>
                  ))}
                </tr>

                {/* Stock Status Row */}
                <tr>
                  <td style={{ padding: '12px 16px', fontWeight: '700', color: '#9ca3af', borderBottom: '1px solid rgba(255,255,255,0.06)' }}>Availability</td>
                  {compareItems.map((p) => (
                    <td key={p.id} style={{ padding: '12px 16px', borderBottom: '1px solid rgba(255,255,255,0.06)', fontWeight: '700', color: p.stock === 'In Stock' ? '#22c55e' : '#ef4444' }}>{p.stock}</td>
                  ))}
                </tr>

                {/* Rating Row */}
                <tr>
                  <td style={{ padding: '12px 16px', fontWeight: '700', color: '#9ca3af', borderBottom: '1px solid rgba(255,255,255,0.06)' }}>Rating</td>
                  {compareItems.map((p) => (
                    <td key={p.id} style={{ padding: '12px 16px', borderBottom: '1px solid rgba(255,255,255,0.06)', fontWeight: '600' }}>★ {p.rating || 5.0}</td>
                  ))}
                </tr>

                {/* Technical Specifications Rows */}
                {specKeys.map((key) => {
                  const isDiff = isSpecDifferent(key);
                  const isHighlighted = highlightDifferences && isDiff;
                  return (
                    <tr key={key} style={{ backgroundColor: isHighlighted ? 'rgba(213, 30, 11, 0.15)' : 'transparent' }}>
                      <td style={{ padding: '12px 16px', fontWeight: '700', color: isHighlighted ? '#D51E0B' : '#9ca3af', borderBottom: '1px solid rgba(255,255,255,0.06)' }}>
                        {key}
                      </td>
                      {compareItems.map((p) => (
                        <td key={p.id} style={{ padding: '12px 16px', borderBottom: '1px solid rgba(255,255,255,0.06)', fontSize: '13px' }}>
                          {getSpecValue(p, key)}
                        </td>
                      ))}
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
};

export default Comparison;
