import React from 'react';

const DIVISIONS = ['Dhaka', 'Chittagong', 'Rajshahi', 'Khulna', 'Barisal', 'Sylhet', 'Rangpur', 'Mymensingh'];

const AddressForm = ({
  title = 'Shipping Address',
  addressData = {},
  onChange,
  showSameAsShipping = false,
  sameAsShipping = true,
  onToggleSame
}) => {
  return (
    <div
      style={{
        backgroundColor: 'var(--bg-secondary, #0c1c28)',
        border: '1px solid var(--border-color, rgba(255, 255, 255, 0.08))',
        borderRadius: '12px',
        padding: '20px',
        display: 'flex',
        flexDirection: 'column',
        gap: '16px'
      }}
    >
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <h3 style={{ fontSize: '16px', fontWeight: '800', color: '#ffffff', margin: 0 }}>
          {title}
        </h3>

        {showSameAsShipping && (
          <label style={{ display: 'flex', alignItems: 'center', gap: '6px', fontSize: '13px', color: '#ffffff', cursor: 'pointer' }}>
            <input
              type="checkbox"
              checked={sameAsShipping}
              onChange={(e) => onToggleSame(e.target.checked)}
              style={{ accentColor: '#D51E0B' }}
            />
            Same as Shipping Address
          </label>
        )}
      </div>

      {(!showSameAsShipping || !sameAsShipping) && (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '12px' }}>
          {/* Address Line */}
          <div style={{ gridColumn: '1 / -1' }}>
            <label style={{ fontSize: '12px', fontWeight: '600', color: '#9ca3af', display: 'block', marginBottom: '4px' }}>
              Street Address / House / Flat / Road *
            </label>
            <input
              type="text"
              required
              placeholder="e.g. House 45, Road 11, Block D, Mirpur"
              value={addressData.address || ''}
              onChange={(e) => onChange({ address: e.target.value })}
              style={{
                width: '100%',
                padding: '10px 12px',
                borderRadius: '8px',
                border: '1px solid rgba(255,255,255,0.15)',
                backgroundColor: '#081621',
                color: '#ffffff',
                fontSize: '13px',
                outline: 'none'
              }}
            />
          </div>

          {/* Division */}
          <div>
            <label style={{ fontSize: '12px', fontWeight: '600', color: '#9ca3af', display: 'block', marginBottom: '4px' }}>
              Division *
            </label>
            <select
              value={addressData.division || 'Dhaka'}
              onChange={(e) => onChange({ division: e.target.value })}
              style={{
                width: '100%',
                padding: '10px 12px',
                borderRadius: '8px',
                border: '1px solid rgba(255,255,255,0.15)',
                backgroundColor: '#081621',
                color: '#ffffff',
                fontSize: '13px',
                outline: 'none'
              }}
            >
              {DIVISIONS.map((d) => (
                <option key={d} value={d}>{d}</option>
              ))}
            </select>
          </div>

          {/* City / District */}
          <div>
            <label style={{ fontSize: '12px', fontWeight: '600', color: '#9ca3af', display: 'block', marginBottom: '4px' }}>
              City / District *
            </label>
            <input
              type="text"
              required
              placeholder="e.g. Dhaka"
              value={addressData.city || ''}
              onChange={(e) => onChange({ city: e.target.value })}
              style={{
                width: '100%',
                padding: '10px 12px',
                borderRadius: '8px',
                border: '1px solid rgba(255,255,255,0.15)',
                backgroundColor: '#081621',
                color: '#ffffff',
                fontSize: '13px',
                outline: 'none'
              }}
            />
          </div>

          {/* Postal Code */}
          <div>
            <label style={{ fontSize: '12px', fontWeight: '600', color: '#9ca3af', display: 'block', marginBottom: '4px' }}>
              Postal Code
            </label>
            <input
              type="text"
              placeholder="e.g. 1207"
              value={addressData.postalCode || ''}
              onChange={(e) => onChange({ postalCode: e.target.value })}
              style={{
                width: '100%',
                padding: '10px 12px',
                borderRadius: '8px',
                border: '1px solid rgba(255,255,255,0.15)',
                backgroundColor: '#081621',
                color: '#ffffff',
                fontSize: '13px',
                outline: 'none'
              }}
            />
          </div>
        </div>
      )}
    </div>
  );
};

export default AddressForm;
